from .nonzero import _nonzero_impl

logger = logging.getLogger(__name__)


def nonzero_numpy(inp):
    """
    Returns a tuple of 1D tensors, one for each dimension of the input,
    containing the indices of the non-zero elements in that dimension.

    This is equivalent to torch.nonzero(...).T or numpy.nonzero() behavior.
    """
    logger.debug("GEMS NONZERO_NUMPY")

    # ``split=True`` makes the rank-2 fast path write the two coordinate
    # vectors as two contiguous buffers instead of building an interleaved
    # (N, 2) tensor and slicing it, which is measurably cheaper on Ascend.
    # Non rank-2 / non power-of-two inputs fall back to the generic path and
    # return the interleaved tensor, which is then split along dim=1 below.
